#define CK(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(2);}}while(0)
__constant__ unsigned table[32]={4660};
template<int KIND,int DEP> __global__ void probe(unsigned long long*ts,unsigned*out,unsigned sentinel,unsigned zero_mask){unsigned tid=threadIdx.x,sum=0,v=0;unsigned long long a=0,b=0;for(int n=0;n<96;n++){if(n==32){asm volatile("mov.u64 %0, %%clock64;":"=l"(a)::"memory");}if constexpr(KIND==0)asm volatile("ld.const.u32 %0,[%1];":"=r"(v):"l"(&table[n==32?(unsigned(a)&zero_mask):0]):"memory");else asm volatile("mov.u32 %0, %%laneid;":"=r"(v));if(n==32)asm volatile("{.reg .pred p;setp.ne.u32 p,%1,%2;@p mov.u64 %0, %%clock64;}":"=l"(b):"r"(DEP?v:tid),"r"(sentinel):"memory");sum+=v;}int idx=blockIdx.x*128+tid;out[idx]=sum;if((tid&31)==0){int owner=blockIdx.x*4+tid/32;ts[owner*2]=a;ts[owner*2+1]=b;}}
int main(){CK(cudaSetDevice(7));unsigned*out;unsigned long long*ts;CK(cudaMalloc(&out,144*128*4));CK(cudaMalloc(&ts,576*16));for(int kind:{0})for(int dep:{0,1}){for(int warm=0;warm<5;warm++){if(kind==0){if(dep)probe<0,1><<<144,128>>>(ts,out,65536,0);else probe<0,0><<<144,128>>>(ts,out,65536,0);}else{if(dep)probe<1,1><<<144,128>>>(ts,out,65536,0);else probe<1,0><<<144,128>>>(ts,out,65536,0);}}CK(cudaDeviceSynchronize());std::vector<unsigned>v(18432);std::vector<unsigned long long>t(1152);CK(cudaMemcpy(v.data(),out,v.size()*4,cudaMemcpyDeviceToHost));CK(cudaMemcpy(t.data(),ts,t.size()*8,cudaMemcpyDeviceToHost));int bad=0;for(int i=0;i<18432;i++)bad+=v[i]!=(kind?unsigned(i%32)*96:4660*96);printf("{\"kind\":\"correctness\",\"unit\":%d,\"dep\":%d,\"bad\":%d}\n",kind,dep,bad);if(bad)return 3;for(int i=0;i<576;i++)printf("{\"kind\":\"cycles\",\"unit\":%d,\"dep\":%d,\"owner\":%d,\"cycles\":%llu}\n",kind,dep,i,t[i*2+1]-t[i*2]);}}
